      "slurm": "#!/bin/bash\n#SBATCH --nodes=2\n\nNPROCS=16\nNPPERSOC=$(($NPROCS>>2))\nsource ~/init.sh\nmake clean && make\nrm -r hpctoolkit*\nmpirun -np $NPROCS -npersocket $NPPERSOC hpcrun -e CPUTIME -e IO -e gpu=nvidia -t ./jacobi\nhpcstruct --gpucfg yes hpctoolkit*\nhpcstruct --gpucfg yes jacobi\nhpcprof -S jacobi.hpcstruct -I jacobi.cpp -I jacobi_kernels.cu -I ./+ hpctoolkit*\necho \"===DONE===\"\n",
      "flux": "#!/bin/bash\n#FLUX: --nodes=2\n\n# The previous attempt to specify '--ntasks=16' failed validation. The directive has been removed.\n# The 'flux mini run' command will now request the 16 tasks, and Flux will distribute them across the 2 allocated nodes.\n# This achieves the same resource allocation as the original intent.\n\nNPROCS=16\nNPPERSOC=$(($NPROCS>>2))\nsource ~/init.sh\nmake clean && make\nrm -r hpctoolkit*\n\n# The 'mpirun -npersocket' option is a process placement hint for the MPI library.\n# It does not have a direct equivalent in Flux and has been omitted.\n# Flux will use its own placement algorithm, which may have performance implications if the application is sensitive to process-to-socket mapping.\nflux mini run -n $NPROCS hpcrun -e CPUTIME -e IO -e gpu=nvidia -t ./jacobi\n\nhpcstruct --gpucfg yes hpctoolkit*\nhpcstruct --gpucfg yes jacobi\nhpcprof -S jacobi.hpcstruct -I jacobi.cpp -I jacobi_kernels.cu -I ./+ hpctoolkit*\necho \"===DONE===\"\n",
