      "slurm": "#!/usr/bin/env bash\n\n#BSUB -J RNAseq\n#BSUB -o logs/snakemake_%J.out\n#BSUB -e logs/snakemake_%J.err\n#BSUB -R \"select[mem>4] rusage[mem=4] \" \n#BSUB -q rna\n\nset -o nounset -o pipefail -o errexit -x\n\n# Load modules\n# Use locally installed packages for Majiq\n# module load fastqc/0.11.7\n# module load samtools/1.12\n# module load STAR/2.7.9a\n# module load subread/1.6.2\n# module load bbtools/38.86\nmodule load singularity/3.9.2\n\n# LSF arguments\nargs=' \n  -q rna \n  -o {log}.out \n  -e {log}.err \n  -J {params.job_name} \n  -R \"{params.memory} span[hosts=1] \" \n  -n {threads} ' \n\n# Run snakemake pipeline\nsnakemake \\\n    --drmaa \"$args\" \\\n    --snakefile Snakefile \\\n    --configfile config.yaml \\\n    --jobs 12 \\\n    --latency-wait 60 \\\n    --rerun-incomplete \\\n    --use-singularity \\\n    --singularity-args \"--bind /beevol/home/rbilab --bind /beevol/home/wellskri --bind /beevol/home/wellskri/packages/bin --bind /tmp:/tmp\"\n    ",
      "flux": "#!/usr/bin/env bash\n\n#FLUX: --job-name=RNAseq\n#FLUX: --output=logs/snakemake_%j.out\n#FLUX: --error=logs/snakemake_%j.err\n#FLUX: --queue=rna\n\n# The LSF resource request '-R \"select[mem>4] rusage[mem=4]\"' for the main Snakemake process has no direct Flux equivalent and has been omitted.\n# This should have minimal performance impact, as the main process is typically not resource-intensive.\n\nset -o nounset -o pipefail -o errexit -x\n\n# Load modules\n# Use locally installed packages for Majiq\n# module load fastqc/0.11.7\n# module load samtools/1.12\n# module load STAR/2.7.9a\n# module load subread/1.6.2\n# module load bbtools/38.86\nmodule load singularity/3.9.2\n\n# Flux arguments for Snakemake cluster submission\n# Note: LSF's memory request (-R) has no direct Flux equivalent and is omitted from the sub-job submission command.\n# This may cause individual sub-jobs to be scheduled on nodes without enough memory, potentially leading to failure.\nflux_submit_args='flux mini submit --queue=rna --output={log}.out --error={log}.err --job-name={params.job_name} --nodes=1 --ntasks={threads}'\n\n# Run snakemake pipeline, replacing the LSF-specific '--drmaa' with the more general '--cluster' flag\nsnakemake \\\n    --cluster \"$flux_submit_args\" \\\n    --snakefile Snakefile \\\n    --configfile config.yaml \\\n    --jobs 12 \\\n    --latency-wait 60 \\\n    --rerun-incomplete \\\n    --use-singularity \\\n    --singularity-args \"--bind /beevol/home/rbilab --bind /beevol/home/wellskri --bind /beevol/home/wellskri/packages/bin --bind /tmp:/tmp\"\n    \n",
