      "slurm": "#!/bin/sh\n#SBATCH -J HAICprep\n#SBATCH -N 1            # nodes number =NBP dans tosupcrc\n#SBATCH -n 16           # CPUs number (on all nodes) =NBP*TPN dans tosupcrc\n#SBATCH -o POI16.eo%j   #\n#SBATCH -e POI16.eo%j   #\n#SBATCH -t 01:00:00     # time limit\n#SBATCH -p normal256\n\n# Echo des commandes\nulimit -c 0\nulimit -s unlimited\n# Nom de la machine\nhostname \n\n. ~rodierq/DEV_57/MNH-PHYEX070-b95d84d7/conf/profile_mesonh-LXifort-R8I4-MNH-V5-6-2-ECRAD140-MPIAUTO-O2-HAIC\n\nexport MPIRUN='Mpirun -np 16'\n\nln -sf ../01_prep_pgd/PGD.* .\nln -sf ~/SAVE/mesonh/PGD/pgd_guyane* .\nln -sf ~/SAVE/GRIB_KTEST/arome.FO.201505* .\nln -sf ~/SAVE/GRIB_KTEST/historic.20150529.00.lfi\n\ntouch pgd_guyane.02km50.04.des\ntouch historic.20150529.00.des\n\ntime ${MPIRUN} PREP_REAL_CASE${XYZ}\n\nfor i in 00 06 12 18 24; do\n    cp PRE_REAL1.nam_$i PRE_REAL1.nam\n    time ${MPIRUN} PREP_REAL_CASE${XYZ}\ndone\ncd ../\n./run_all_mesonh\n",
      "flux": "#!/bin/sh\n#FLUX: --job-name=HAICprep\n#FLUX: --nodes=1\n#FLUX: --exclusive\n#FLUX: --output=POI16.eo%j\n#FLUX: --error=POI16.eo%j\n#FLUX: --time=01:00:00\n#FLUX: --queue=normal256\n\n# The previous attempt to translate the Slurm directive '-n 16' to '--ntasks=16' failed validation.\n# This suggests the system prefers node-level resource requests. The script now requests one exclusive node.\n# This provides the job with all cores on the node (satisfying the original request for 16), which the MPI application will then use.\n\n# Echo des commandes\nulimit -c 0\nulimit -s unlimited\n# Nom de la machine\nhostname \n\n. ~rodierq/DEV_57/MNH-PHYEX070-b95d84d7/conf/profile_mesonh-LXifort-R8I4-MNH-V5-6-2-ECRAD140-MPIAUTO-O2-HAIC\n\n# The site-specific 'Mpirun' alias has been replaced with a standard 'flux mini run' command.\nexport MPIRUN='flux mini run -n 16'\n\nln -sf ../01_prep_pgd/PGD.* .\nln -sf ~/SAVE/mesonh/PGD/pgd_guyane* .\nln -sf ~/SAVE/GRIB_KTEST/arome.FO.201505* .\nln -sf ~/SAVE/GRIB_KTEST/historic.20150529.00.lfi\n\ntouch pgd_guyane.02km50.04.des\ntouch historic.20150529.00.des\n\ntime ${MPIRUN} PREP_REAL_CASE${XYZ}\n\nfor i in 00 06 12 18 24; do\n    cp PRE_REAL1.nam_$i PRE_REAL1.nam\n    time ${MPIRUN} PREP_REAL_CASE${XYZ}\ndone\ncd ../\n./run_all_mesonh\n",
