      "total_time": 8.209208011627197,
      "step_count": 2,
      "slurm": "#!/bin/sh --login\n\n#BSUB -q 1nd\n\nWorkDir=__WORKDIR__\nSampleType=__SAMPLETYPE__\nID=__ID__\n\nexport SCRAM_ARCH=slc6_amd64_gcc630\ncd /afs/cern.ch/work/c/chenyi/CMSSW/CMSSW_10_3_0/src/\neval `scramv1 runtime -sh`\ncd - > /dev/null\n\nexport X509_USER_PROXY=$PhysicsWorkspace/HI2018HLT/CommonCode/proxy/x509up_proxy\necho $X509_USER_PROXY\n\nTemplate=$WorkDir/ExportedMenuPFNewTrackingV4.py\n\nFileList=`echo \"__INPUT__\" | tr '@' ' ' | sed \"s/[ ,]*$//\"`\n\necho \"List of files = $FileList\"\necho \"ID = $ID\"\necho \"Sample = $SampleType\"\n\ncat $Template \\\n   | sed \"s#__FILE__#$FileList#g\" \\\n   > RunJob.py\ncat RunJob.py | bzip2 > $WorkDir/Result/RunJob_${SampleType}_${ID}.py.bz2\n\ncp $WorkDir/setup_dev_CMSSW_10_3_0_HLT_cff.py .\n\ncp -r $WorkDir/Sample* .\n\nmkdir -p $WorkDir/Result/\n\ncmsRun RunJob.py >& Log_${ID}\nbzip2 Log_${ID}\nmv Log_${ID}.bz2 $WorkDir/Result/Log_${SampleType}_${ID}.bz2\nmv openHLT.root $WorkDir/Result/openHLT_${SampleType}_${ID}.root\n\n",
      "flux": "#!/bin/sh --login\n\n#FLUX: --queue=1nd\n\n# The original LSF script did not specify any resource requirements (e.g., nodes, cores).\n# The job will be scheduled with the system's default resource allocation, which is typically a single core.\n# If the 'cmsRun' application requires more resources, this could lead to poor performance.\n\nWorkDir=__WORKDIR__\nSampleType=__SAMPLETYPE__\nID=__ID__\n\nexport SCRAM_ARCH=slc6_amd64_gcc630\ncd /afs/cern.ch/work/c/chenyi/CMSSW/CMSSW_10_3_0/src/\neval `scramv1 runtime -sh`\ncd - > /dev/null\n\nexport X509_USER_PROXY=$PhysicsWorkspace/HI2018HLT/CommonCode/proxy/x509up_proxy\necho $X509_USER_PROXY\n\nTemplate=$WorkDir/ExportedMenuPFNewTrackingV4.py\n\nFileList=`echo \"__INPUT__\" | tr '@' ' ' | sed \"s/[ ,]*$//\"`\n\necho \"List of files = $FileList\"\necho \"ID = $ID\"\necho \"Sample = $SampleType\"\n\ncat $Template \\\n   | sed \"s#__FILE__#$FileList#g\" \\\n   > RunJob.py\ncat RunJob.py | bzip2 > $WorkDir/Result/RunJob_${SampleType}_${ID}.py.bz2\n\ncp $WorkDir/setup_dev_CMSSW_10_3_0_HLT_cff.py .\n\ncp -r $WorkDir/Sample* .\n\nmkdir -p $WorkDir/Result/\n\ncmsRun RunJob.py >& Log_${ID}\nbzip2 Log_${ID}\nmv Log_${ID}.bz2 $WorkDir/Result/Log_${SampleType}_${ID}.bz2\nmv openHLT.root $WorkDir/Result/openHLT_${SampleType}_${ID}.root\n\n",
