      "slurm": "#!/bin/bash -l\n#SBATCH --nodes=6\n#SBATCH --ntasks=96\n#SBATCH --time=00:30:00\n\nsource /ssoft/spack/bin/slmodules.sh -r stable \n\nmodule purge\nmodule load gcc/5.3.0 mvapich2/2.2b openblas/0.2.18 cp2k/3.0-mpi\nexport OMP_NUM_THREADS=1\n\ndate_start=$(date +%s)\nsrun cp2k.popt -i *.inp -o output.out                 #running command\ndate_end=$(date +%s)\ntime_run=$((date_end-date_start))\necho \"096_cpus $time_run seconds\"\n\nrm -f GTH_BASIS_SETS POTENTIAL *xyz *restart          #remove useless big files (please!) \n",
      "flux": "#!/bin/bash -l\n#FLUX: --nodes=6\n#FLUX: --exclusive\n#FLUX: --time=00:30:00\n\n# Previous attempts to specify task counts directly (--ntasks=96, --ntasks-per-node=16) failed validation.\n# This suggests the system prefers node-level resource requests. This version requests 6 exclusive nodes.\n# This provides the job with all cores on each node, which the 'flux mini run' command will then use to place the 96 tasks (16 per node).\n\nsource /ssoft/spack/bin/slmodules.sh -r stable \n\nmodule purge\nmodule load gcc/5.3.0 mvapich2/2.2b openblas/0.2.18 cp2k/3.0-mpi\nexport OMP_NUM_THREADS=1\n\ndate_start=$(date +%s)\n# The srun command is replaced with 'flux mini run' to launch the MPI application with 96 total tasks across the 6 allocated nodes.\nflux mini run -n 96 cp2k.popt -i *.inp -o output.out\ndate_end=$(date +%s)\ntime_run=$((date_end-date_start))\necho \"096_cpus $time_run seconds\"\n\nrm -f GTH_BASIS_SETS POTENTIAL *xyz *restart          #remove useless big files (please!) \n",
