      "slurm": "#!/bin/bash -l\n#SBATCH --nodes=2  --time=04:00:00  \n#SBATCH -C gpu \n#SBATCH --account m1759\n#SBATCH --gres=gpu:8\n#SBATCH --exclusive\n#SBATCH -c 80\n\nmodule load pytorch/v1.4.0-gpu\nmodule list\nexport HDF5_USE_FILE_LOCKING=FALSE\n\nnodes=$(scontrol show hostnames $SLURM_JOB_NODELIST) # Getting the node names\nnodes_array=( $nodes )\nworker_num=$(($SLURM_JOB_NUM_NODES - 1))\n\nmaster_node=${nodes_array[0]}\n\nfor ((  i=0; i<=$worker_num; i++ ))\ndo\n  node_i=${nodes_array[$i]}\n  srun --nodes=1 --ntasks=1 -w $node_i python -m torch.distributed.launch --nproc_per_node=8 --nnodes=8 --node_rank=$i --master_addr=$master_node train.py --run_num=13 &\n  pids[${i}]=$!\n  echo \"Training started on node $i\"\ndone\n\n# Wait for completion\nfor pid in ${pids[*]}; do\n    wait $pid\ndone\n\ndate\n\n",
      "flux": "#!/bin/bash -l\n#FLUX: --nodes=2\n#FLUX: --time=04:00:00\n#FLUX: --gpus=8\n#FLUX: --exclusive\n\n# The Slurm constraint '-C gpu' has no direct equivalent in Flux and has been omitted.\n# GPU nodes are typically selected by specifying a GPU queue or partition.\n\n# The Slurm '--account m1759' directive has no direct equivalent in Flux and has been omitted.\n# Account/project information is often handled by site-specific configurations.\n\n# The Slurm directive '-c 80' (cpus-per-task) is redundant when '--exclusive' is used, as exclusive access grants all CPUs on the node. It has been omitted.\n\nmodule load pytorch/v1.4.0-gpu\nmodule list\nexport HDF5_USE_FILE_LOCKING=FALSE\n\n# The original script used a complex loop with srun to manually start PyTorch on each node.\n# This is replaced by a single 'flux mini run' command that starts the modern 'torchrun' launcher on each node.\n# This is a more robust and standard way to launch multi-node PyTorch jobs.\n\n# Get the hostname of the master node (rank 0 of the job).\nMASTER_ADDR=$(flux exec -r 0 hostname)\n\n# Note: The original script specified '--nnodes=8' to torch.distributed.launch, which appears to be a bug for a 2-node job.\n# This has been corrected to use the actual number of nodes allocated to the job (2).\n\n# Launch one instance of torchrun on each of the 2 nodes. \n# torchrun will then launch 8 worker processes per node.\nflux mini run -n 2 -N 2 -ppn 1 torchrun \\\n  --nnodes=2 --nproc_per_node=8 \\\n  --master_addr=$MASTER_ADDR --master_port=29500 --node_rank=$FLUX_TASK_RANK \\\n  train.py --run_num=13\n\ndate\n",
