      "slurm": "#! /usr/bin/env bash\n\n#BSUB -J NET-seq\n#BSUB -o logs/snake_%J.out\n#BSUB -e logs/snake_%J.err\n\nset -o nounset -o pipefail -o errexit -x\n\nmodule load fastqc\nmodule load bowtie2\nmodule load samtools\nmodule load subread\nmodule load gcc/7.4.0\nmodule load R/4.0.3\n\nmkdir -p logs\n\n\n# Function to run snakemake\nrun_snakemake() {\n    local snake_file=$1\n    local config_file=$2\n\n    args='\n        -oo {log.out} \n        -eo {log.err} \n        -J {params.job_name}\n        -R \"rusage[mem={params.memory}] span[hosts=1]\"\n        -n {threads} '\n\n    snakemake -n \\\n        --snakefile $snake_file \\\n        --drmaa \"$args\" \\\n        --jobs 100 \\\n        --configfiles $config_file\n}\n\n\n# Run pipeline to process mNET-seq reads\npipe_dir=src/pipelines\nsamples=SAMPLES.yaml\n\nsnake=$pipe_dir/NETseq.snake\nconfig=NETseq.yaml\n\nrun_snakemake $snake \"$samples $config\"\n\n# Run pipeline to identify pause sites\nsnake=$pipe_dir/pauses.snake\nconfig=pauses.yaml\n\nrun_snakemake $snake \"$samples $config\"\n\n\n",
      "flux": "#! /usr/bin/env bash\n\n#FLUX: --job-name=NET-seq\n#FLUX: --output=logs/snake_%j.out\n#FLUX: --error=logs/snake_%j.err\n\n# The original LSF script did not specify any resource requirements (e.g., nodes, cores, or a queue) for the main Snakemake process.\n# The job will be scheduled with the system's default resource allocation, which is typically a single core.\n# This should have minimal performance impact as the main process primarily submits and monitors sub-jobs.\n\nset -o nounset -o pipefail -o errexit -x\n\nmodule load fastqc\nmodule load bowtie2\nmodule load samtools\nmodule load subread\nmodule load gcc/7.4.0\nmodule load R/4.0.3\n\nmkdir -p logs\n\n\n# Function to run snakemake\nrun_snakemake() {\n    local snake_file=$1\n    local config_file=$2\n\n    # The LSF '-R' memory request has no direct equivalent in standard Flux and has been omitted from the sub-job submission command.\n    # The performance implication is that individual Snakemake jobs may be scheduled on nodes without enough memory, potentially causing them to fail.\n    flux_submit_args='flux mini submit --output={log.out} --error={log.err} --job-name={params.job_name} --nodes=1 --ntasks={threads}'\n\n    snakemake -n \\\n        --snakefile $snake_file \\\n        --cluster \"$flux_submit_args\" \\\n        --jobs 100 \\\n        --configfiles $config_file\n}\n\n\n# Run pipeline to process mNET-seq reads\npipe_dir=src/pipelines\nsamples=SAMPLES.yaml\n\nsnake=$pipe_dir/NETseq.snake\nconfig=NETseq.yaml\n\nrun_snakemake $snake \"$samples $config\"\n\n# Run pipeline to identify pause sites\nsnake=$pipe_dir/pauses.snake\nconfig=pauses.yaml\n\nrun_snakemake $snake \"$samples $config\"\n\n\n",
