      "slurm": "#!/bin/bash\n#COBALT -q full-node\n#COBALT -n 1\n#COBALT -t 240\n#COBALT -A datascience\n#COBALT --attrs filesystems=home,grand,eagle,theta-fs0\n# Necessary for Bash shells\n. /etc/profile\n\n# Tensorflow optimized for A100 with CUDA 11\nmodule load conda/pytorch\n# module load conda/pytorch\n\n# Activate conda env\nconda activate pycords\n# conda activate base\nexport PYTHONPATH=/lus/grand/projects/datascience/ianwixom/expcifar:$PYTHONPATH\n\n# User Configuration\n# INIT_SCRIPT=$PWD/activate-dh.sh\nCOBALT_JOBSIZE=1\nRANKS_PER_NODE=8\n\n# Initialization of environment\n# source $INIT_SCRIPT\nmodule list\nmpirun -x LD_LIBRARY_PATH -x PYTHONPATH -x PATH -n $(( $COBALT_JOBSIZE * $RANKS_PER_NODE )) -N $RANKS_PER_NODE --hostfile $COBALT_NODEFILE python cifar10cordsmodel.py",
      "flux": "#!/bin/bash\n\n#flux: -N 1\n#flux: --time-limit=240m\n\n# Note: Cobalt -q directive (full-node) does not have a direct Flux equivalent.\n# Performance consideration: Queue selection not preserved. Job may run on different hardware/queue.\n# Note: Cobalt -A directive (datascience) does not have a direct Flux equivalent.\n# Performance consideration: Account/project tracking not preserved.\n# Note: Cobalt --attrs directive (filesystems=home,grand,eagle,theta-fs0) does not have a direct Flux equivalent.\n# Performance consideration: Filesystem access requirements not preserved. Job may not have access to required filesystems.\n# Note: Cobalt uses -n for nodes, Flux uses -N. Converting 1 node.\n# Note: RANKS_PER_NODE=8 means 8 tasks per node, so total tasks = 1 * 8 = 8.\n\n# Necessary for Bash shells\n. /etc/profile\n\n# Tensorflow optimized for A100 with CUDA 11\nmodule load conda/pytorch\n# module load conda/pytorch\n\n# Activate conda env\nconda activate pycords\n# conda activate base\nexport PYTHONPATH=/lus/grand/projects/datascience/ianwixom/expcifar:$PYTHONPATH\n\n# User Configuration\n# INIT_SCRIPT=$PWD/activate-dh.sh\nCOBALT_JOBSIZE=1\nRANKS_PER_NODE=8\n\n# Initialization of environment\n# source $INIT_SCRIPT\nmodule list\n\n# Note: Cobalt uses COBALT_NODEFILE for host specification. Flux does not have a direct equivalent.\n# Using flux run instead of mpirun for better integration.\n# Performance consideration: MPI process placement may differ from Cobalt behavior.\nflux run -N 1 -n $(( $COBALT_JOBSIZE * $RANKS_PER_NODE )) -o cpu-affinity=per-task python cifar10cordsmodel.py\n",
