      "slurm": "#!/bin/bash\n#SBATCH --job-name=TestGPUOnSaga\n#SBATCH --account=nn<XXXX>k\n#SBATCH --time=05:00\n#SBATCH --mem-per-cpu=4G\n#SBATCH --qos=devel\n#SBATCH --partition=accel\n#SBATCH --gpus=1\n\n## Set up job environment:\nset -o errexit  # Exit the script on any error\nset -o nounset  # Treat any unset variables as an error\n\nmodule --quiet purge  # Reset the modules to the system default\nmodule load TensorFlow/2.6.0-foss-2021a-CUDA-11.3.1\nmodule list\n\n# Setup monitoring\nnvidia-smi --query-gpu=timestamp,utilization.gpu,utilization.memory \\\n\t--format=csv --loop=1 > \"gpu_util-$SLURM_JOB_ID.csv\" &\nNVIDIA_MONITOR_PID=$!  # Capture PID of monitoring process\n# Run our computation\npython gpu_intro.py\n# After computation stop monitoring\nkill -SIGINT \"$NVIDIA_MONITOR_PID\"\n",
      "flux": "#!/bin/bash\n\n# Flux batch script\n#\n# This is a self-submitting Flux script: run it directly (e.g., `./testgpu_saga.flux.sh`).\n# It will submit itself to Flux with the translated resource requests.\n\n# Translated resources from Slurm:\n#   --time=05:00        -> -t 5m\n#   --gpus=1            -> -g 1\n#   --mem-per-cpu=4G    -> (not translated; see note)\nJOBID=$(flux batch -N 1 -n 1 -g 1 -t 5m --wrap \"bash $0 __flux_inner\")\n\necho \"Submitted Flux job: $JOBID\"\n\nif [ \"${1:-}\" = \"__flux_inner\" ]; then\n  # NOTE: Slurm --job-name=TestGPUOnSaga not translated.\n  # Performance/ops implication: job identification may be less convenient; runtime performance is unaffected.\n\n  # NOTE: Slurm --account=nn<XXXX>k not translated.\n  # Performance/ops implication: accounting/charging may not be applied as intended; depending on site policy, submission may require a project/account specified out-of-band.\n\n  # NOTE: Slurm --qos=devel not translated.\n  # Performance implication: job priority/time limits associated with the QoS will not be applied; scheduling behavior may change.\n\n  # NOTE: Slurm --partition=accel not translated.\n  # Performance implication: without a queue/constraint mapping, the job may run on any eligible GPU resources; you are not forcing the accel partition.\n\n  # NOTE: Slurm --mem-per-cpu=4G not translated.\n  # Performance implication: without a per-core memory reservation/limit, the job may contend for memory or be OOM-killed, affecting reliability/performance.\n\n  set -o errexit\n  set -o nounset\n\n  module --quiet purge\n  module load TensorFlow/2.6.0-foss-2021a-CUDA-11.3.1\n  module list\n\n  # Setup monitoring\n  # NOTE: SLURM_JOB_ID is Slurm-specific; use FLUX_JOB_ID if available.\n  JOBTAG=\"${FLUX_JOB_ID:-job}\"\n\n  nvidia-smi --query-gpu=timestamp,utilization.gpu,utilization.memory \\\n    --format=csv --loop=1 > \"gpu_util-${JOBTAG}.csv\" &\n  NVIDIA_MONITOR_PID=$!\n\n  # Run computation within the allocation\n  flux run -n 1 -g 1 python gpu_intro.py\n\n  kill -SIGINT \"$NVIDIA_MONITOR_PID\"\nfi\n",
