      "slurm": "#!/bin/bash\n#COBALT -n 4\n#COBALT -t 1:00:00\n#COBALT -q training --attrs mcdram=cache:numa=quad\n#COBALT -A SDL_Workshop -O tensorflow_imagenet\n\n#submisstion script for running tensorflow_mnist with horovod\n\necho \"Running Cobalt Job $COBALT_JOBID.\"\n\n#Loading modules\nmodule load datascience/tensorflow-1.14\n\nPROC_PER_NODE=1\n\n#note: Setting threads to a low count for demonstration purposes\naprun -n $(($COBALT_JOBSIZE*$PROC_PER_NODE)) -N $PROC_PER_NODE \\\n    -j 2 -d 128 -cc depth \\\n    -e OMP_NUM_THREADS=8 \\\n    -e KMP_BLOCKTIME=0 \\\n    -e HOROVOD_TIMELINE=./timeline.json \\\n    -e TIMELINE_MARK_CYCLES=1 \\\n    python tensorflow_synthetic_benchmark.py --num_intra=8 --num_inter=2 --num-iters=10 --device cpu\n\n",
      "flux": "#!/bin/bash\n\n# Flux batch script\n#\n# This is a self-submitting Flux script: run it directly (e.g., `./tensorflow_imagenet.flux.sh`).\n# It will submit itself to Flux with the translated resource requests.\n\n# Translated resources from Cobalt:\n#   #COBALT -n 4       -> request 4 nodes  (-N 4)\n#   #COBALT -t 1:00:00 -> -t 1h\n#\n# aprun options:\n#   PROC_PER_NODE=1 and aprun -n ($COBALT_JOBSIZE*$PROC_PER_NODE) -> 4 ranks total\n#   aprun -d 128 (CPUs per rank) -> request -c 128\nJOBID=$(flux batch -N 4 -n 4 -c 128 -t 1h --wrap \"bash $0 __flux_inner\")\n\necho \"Submitted Flux job: $JOBID\"\n\nif [ \"${1:-}\" = \"__flux_inner\" ]; then\n  # NOTE: Cobalt -q training and --attrs mcdram=cache:numa=quad not translated.\n  # Performance implication: without memory-mode/NUMA placement controls, memory bandwidth/latency and overall performance may differ.\n\n  # NOTE: Cobalt -A SDL_Workshop not translated.\n  # Performance/ops implication: accounting/charging may not be applied as intended; site may require account/project out-of-band.\n\n  # NOTE: Cobalt -O tensorflow_imagenet (output prefix) not translated.\n  # Performance implication: none; operational implication: output naming may differ.\n\n  echo \"Running Flux Job ${FLUX_JOB_ID:-unknown}.\"\n\n  module load datascience/tensorflow-1.14\n\n  PROC_PER_NODE=1\n  TOTAL_PROCS=$((4*PROC_PER_NODE))\n\n  # Replace aprun with Flux launch; keep the same threading intent.\n  flux run -N 4 -n ${TOTAL_PROCS} -c 128 \\\n    env OMP_NUM_THREADS=8 \\\n        KMP_BLOCKTIME=0 \\\n        HOROVOD_TIMELINE=./timeline.json \\\n        TIMELINE_MARK_CYCLES=1 \\\n    python tensorflow_synthetic_benchmark.py --num_intra=8 --num_inter=2 --num-iters=10 --device cpu\nfi\n",
