      "slurm": "#!/bin/sh\n#PBS -N hddm-paper\n#PBS -r n\n#PBS -l nodes=20:ppn=8\n#PBS -l walltime=10:00:00\n\nsource hddm_venv2/bin/activate\n\ncd HDDM-paper\n\necho \"Launching controller\"\nipcontroller --profile=mpi &\nsleep 10\n\necho \"Launching engines\"\nmpirun -np 160 --machinefile $PBS_NODEFILE -x PATH -x PYTHON_PATH -x VIRTUAL_ENV -wd ~/HDDM-paper ipengine --profile=mpi &\nsleep 10\n\necho \"Launching job\"\npython ~/HDDM-paper/run_estimation.py -r -a --profile mpi --parallel --all -st -sz -z\n",
      "flux": "#!/bin/bash\n\n# Flux batch script\n#\n# This is a self-submitting Flux script: run it directly (e.g., `./hddm-paper.flux.sh`).\n# It will submit itself to Flux with the translated resource requests.\n\n# Translated resources from PBS:\n#   -l nodes=20:ppn=8     -> -N 20 and (best-effort) -n 160 (20*8)\n#   -l walltime=10:00:00  -> -t 10h\nJOBID=$(flux batch -N 20 -n 160 -t 10h --wrap \"bash $0 __flux_inner\")\n\necho \"Submitted Flux job: $JOBID\"\n\nif [ \"${1:-}\" = \"__flux_inner\" ]; then\n  # NOTE: PBS -N hddm-paper not translated.\n  # Performance/ops implication: job identification may be less convenient; runtime performance is unaffected.\n\n  # NOTE: PBS -r n (non-rerunnable) not translated.\n  # Performance implication: none; operational implication: rerun behavior, if any, will follow Flux/site policy.\n\n  # NOTE: PBS_NODEFILE is PBS-specific and will not exist under Flux.\n  # Performance implication: none; operational implication: mpirun machinefile-based launch would fail; we avoid it.\n\n  # Activate environment\n  source hddm_venv2/bin/activate\n\n  cd HDDM-paper || exit 1\n\n  echo \"Launching controller\"\n  ipcontroller --profile=mpi &\n  sleep 10\n\n  echo \"Launching engines\"\n  # Under Flux, launch engines as a Flux job step across the allocated ranks.\n  # We set the working directory via bash -lc + cd.\n  flux run -n 160 bash -lc 'cd ~/HDDM-paper && exec ipengine --profile=mpi' &\n  sleep 10\n\n  echo \"Launching job\"\n  flux run -n 1 python ~/HDDM-paper/run_estimation.py -r -a --profile mpi --parallel --all -st -sz -z\nfi\n",
