      "slurm": "#!/bin/bash\n#PBS -q h-debug              # <-------------- \u6295\u5165\u3059\u308b\u30ad\u30e5\u30fc\u3092\u6307\u5b9a\u3059\u308b\n#PBS -l select=2:mpiprocs=2:ompthreads=1  #<-- \u5b9f\u884c\u3057\u305f\u3044\u30ce\u30fc\u30c9\u6570\u3068\u3001\u30ce\u30fc\u30c9\u3042\u305f\u308a\u30d7\u30ed\u30bb\u30b9\u6570\u3092\u8a18\u8ff0\u3059\u308b\uff08\u3053\u3053\u3067\u306f\u5408\u8a08\uff14\u30d7\u30ed\u30bb\u30b9\uff09\n#PBS -W group_list=pz0xxx    # <-------------- \u81ea\u5206\u306e\u30b0\u30eb\u30fc\u30d7\u540d\u306b\u66f8\u304d\u63db\u3048\u308b\n#PBS -l walltime=00:15:00    # <-------------- \u5b9f\u884c\u6642\u9593\u4e0a\u9650\u3092\u6307\u5b9a\u3059\u308b\n\nGROUP=$(id -ng)\nMYDIR=/lustre/${GROUP}/${USER}\nexport HOME=$MYDIR\n\n. $MYDIR/env.sh\n\ncd $MYDIR\n\n# \u30c7\u30d0\u30c3\u30b0\u51fa\u529b\uff1a Chainer \u3068 CuPy \u306e\u30d0\u30fc\u30b8\u30e7\u30f3\u3092\u8868\u793a\npython -c \"import chainer; print(chainer.__version__)\"\npython -c \"import cupy; print(cupy.cuda.nccl.get_version())\"\n\nmpiexec -x PYTHONUSERBASE \\\n        python ./train_mnist.py -g --communicator pure_nccl\n\n",
      "flux": "#!/bin/bash\n\n# Flux batch script\n#\n# This is a self-submitting Flux script: run it directly.\n# It will submit itself to Flux with the translated resource requests.\n\n# Translated resources from PBS:\n#   select=2:mpiprocs=2:ompthreads=1 -> -N 2 -n 4 -c 1\n#   walltime=00:15:00               -> -t 15m\nJOBID=$(flux batch -N 2 -n 4 -c 1 -t 15m --wrap \"bash $0 __flux_inner\")\n\necho \"Submitted Flux job: $JOBID\"\n\nif [ \"${1:-}\" = \"__flux_inner\" ]; then\n  # NOTE: PBS -q h-debug not translated.\n  # Performance implication: without a queue/constraint mapping, the job may run on any eligible resources; you are not forcing the h-debug queue.\n\n  # NOTE: PBS -W group_list=pz0xxx not translated.\n  # Performance/ops implication: group/accounting/authorization controls may differ; site policy may require this out-of-band.\n\n  GROUP=$(id -ng)\n  MYDIR=/lustre/${GROUP}/${USER}\n  export HOME=$MYDIR\n\n  . \"$MYDIR/env.sh\"\n\n  cd \"$MYDIR\" || exit 1\n\n  # Debug output\n  flux run -n 1 python -c \"import chainer; print(chainer.__version__)\"\n  flux run -n 1 python -c \"import cupy; print(cupy.cuda.nccl.get_version())\"\n\n  # Prefer Flux to launch ranks within the allocation.\n  flux run -n 4 -c 1 env PYTHONUSERBASE=\"$PYTHONUSERBASE\" \\\n    python ./train_mnist.py -g --communicator pure_nccl\nfi\n",
