      "slurm": "#!/bin/bash\n\n#SBATCH -n40 -N16 #Number of cores and nodes\n#SBATCH --ntasks-per-node=40\n#SBATCH -p general --time=24:00:00\n## OMP_NUM_THREADS controls the number of threads your application use\n## This variable cat be set by the following command :\n\nulimit -s unlimited\nmodule load gcc/5.4.0\nmodule load openmpi/1.10.3-gcc_5.4.0\nmodule load cmake\nmodule load mkl\n\nsource /projects/opt/intel/parallel_studio_xe_2016/mkl/bin/mklvars.sh intel64\nexport OMP_NUM_THREADS=40\nexport KMP_STACKSIZE=3200M\n\n\n## Copy files to work directory:\n#cp $SUBMITDIR/YourDatafile $SCRATCH\n\n## Mark outfiles for automatic copying to $SUBMITDIR:\n#chkfile YourOutputfile\n\n## Run command\n./run.sh \n",
      "flux": "#!/bin/bash\n\n# Flux batch script\n#\n# This is a self-submitting Flux script: run it directly (e.g., `./run_openmp_mpi.flux.sh`).\n# It will submit itself to Flux with the translated resource requests.\n\n# Translated resources from Slurm:\n#   -N16                 -> -N 16\n#   -n40                 -> -n 40 (total ranks)\n#   --time=24:00:00      -> -t 24h\nJOBID=$(flux batch -N 16 -n 40 -t 24h --wrap \"bash $0 __flux_inner\")\n\necho \"Submitted Flux job: $JOBID\"\n\nif [ \"${1:-}\" = \"__flux_inner\" ]; then\n  # NOTE: Slurm --ntasks-per-node=40 not translated.\n  # Performance implication: without an explicit per-node task placement request, ranks may be distributed differently across nodes,\n  # which can change performance (e.g., network traffic, NUMA locality) and may not match the intended layout.\n\n  # NOTE: Slurm -p general not translated.\n  # Performance implication: without a queue/constraint mapping, the job may run on any eligible resources; you are not forcing the 'general' partition.\n\n  ulimit -s unlimited\n  module load gcc/5.4.0\n  module load openmpi/1.10.3-gcc_5.4.0\n  module load cmake\n  module load mkl\n\n  source /projects/opt/intel/parallel_studio_xe_2016/mkl/bin/mklvars.sh intel64\n  export OMP_NUM_THREADS=40\n  export KMP_STACKSIZE=3200M\n\n  # Run within the allocation granted by `flux batch`.\n  # If ./run.sh launches MPI internally (e.g., mpirun/srun), it should be adjusted to use `flux run`.\n  flux run -n 40 ./run.sh\nfi\n",
