      "slurm": "#!/bin/bash\n#BSUB -J {{ job_name }}\n#BSUB -q {{ job_queue }}\n#BSUB -cwd {{ job_workspace }}\n{% get_now as current %}#BSUB -o {{ job_name }}-{{ current }}.out\n#BSUB -e {{ job_name }}-{{ current }}.out\n\n{% if ram_size %}\n#BSUB -R \"rusage[mem={{ ram_size }}M]\"\n{% endif %}\n\n{% if gpu_per_node or use_gpu %}\n#BSUB -n {{ nodes|default:1|multi:cores_per_node|default:1 }}\n#BSUB -R \"span[ptile={{ cores_per_node|default:1 }}]{% if ram_size %} rusage[mem={{ ram_size }}M]{% endif %}\"\n#BSUB -gpu \"num={{ gpu_per_node|default:1 }}{% if gpu_resource_name %}:mig={{ gpu_resource_name }}{% endif %}:j_exclusive=yes\"\n{% else %}\n#BSUB -n {{ nodes|default:1|multi:cores_per_node|default:1 }}\n{% endif %}\n{% if run_time %}#BSUB -W {% format_lsf_walltime run_time %}{% endif %}\n\nENV_JOB_ID=$LSB_JOBID\n\n\n",
      "flux": "#!/bin/bash\n\n# Flux batch script\n#\n# NOTE: The input is an LSF batch-file *template* (Jinja-style {{...}} / {%...%}).\n# Flux cannot interpret these template directives directly. Below is a Flux-oriented template that\n# preserves the same user-provided variables as shell environment variables.\n#\n# Usage example (set variables, then run the script):\n#   export JOB_NAME=myjob JOB_QUEUE=... JOB_WORKSPACE=/path NODES=1 CORES_PER_NODE=4 GPUS_PER_NODE=1 RUN_TIME=2h\n#   ./flux_submit.sh\n\n# Required/optional inputs (as environment variables):\n#   JOB_NAME, JOB_WORKSPACE\n#   NODES (default 1)\n#   CORES_PER_NODE (default 1)\n#   GPUS_PER_NODE (default 0)\n#   RUN_TIME (e.g. 30m, 2h, 1d)\n#   RAM_SIZE_MB (not translated; see note)\n#   GPU_RESOURCE_NAME (not translated; see note)\n#   JOB_QUEUE (not translated; site-specific)\n\nJOB_NAME=${JOB_NAME:?set JOB_NAME}\nJOB_WORKSPACE=${JOB_WORKSPACE:?set JOB_WORKSPACE}\nNODES=${NODES:-1}\nCORES_PER_NODE=${CORES_PER_NODE:-1}\nGPUS_PER_NODE=${GPUS_PER_NODE:-0}\nRUN_TIME=${RUN_TIME:-}\nRAM_SIZE_MB=${RAM_SIZE_MB:-}\nGPU_RESOURCE_NAME=${GPU_RESOURCE_NAME:-}\nJOB_QUEUE=${JOB_QUEUE:-}\n\nTOTAL_TASKS=$((NODES * CORES_PER_NODE))\n\n# NOTE: LSF -q {{ job_queue }} not translated.\n# Performance implication: without a queue/constraint mapping, the job may run on any eligible resources; you are not forcing a specific queue.\n\n# NOTE: LSF rusage[mem=...] not translated.\n# Performance implication: without a memory reservation/limit, the job may contend for memory or be OOM-killed, affecting reliability/performance.\n\n# NOTE: LSF -gpu ... mig=... and j_exclusive=yes not translated.\n# Performance implication: without MIG/exclusive GPU constraints, GPU sharing/type may differ, potentially reducing performance.\n\n# Build flux batch options\nBATCH_OPTS=\"-N ${NODES} -n ${TOTAL_TASKS} -c 1\"\n\nif [ \"${GPUS_PER_NODE}\" -gt 0 ]; then\n  # Flux portable GPU request is count-based; total GPUs = NODES * GPUS_PER_NODE\n  TOTAL_GPUS=$((NODES * GPUS_PER_NODE))\n  BATCH_OPTS=\"${BATCH_OPTS} -g ${TOTAL_GPUS}\"\nfi\n\nif [ -n \"${RUN_TIME}\" ]; then\n  BATCH_OPTS=\"${BATCH_OPTS} -t ${RUN_TIME}\"\nfi\n\n# Output naming equivalent (timestamped)\nSTAMP=$(date +%Y%m%d-%H%M%S)\nOUTFILE=\"${JOB_NAME}-${STAMP}.out\"\n\n# Submit\nJOBID=$(flux batch ${BATCH_OPTS} -o output=\"${OUTFILE}\" --wrap \"bash $0 __flux_inner\")\necho \"Submitted Flux job: ${JOBID}\"\n\nif [ \"${1:-}\" = \"__flux_inner\" ]; then\n  export ENV_JOB_ID=\"${FLUX_JOB_ID:-}\"\n  cd \"${JOB_WORKSPACE}\" || exit 1\n\n  # Put your workload command(s) here.\n  # Example:\n  # flux run -n ${TOTAL_TASKS} <your_command>\n  :\nfi\n",
