      "slurm": "#! /usr/bin/env bash\n\n#BSUB -J NET-seq\n#BSUB -o logs/snake_%J.out\n#BSUB -e logs/snake_%J.err\n\nset -o nounset -o pipefail -o errexit -x\n\nmodule load fastqc\nmodule load bowtie2\nmodule load samtools\nmodule load subread\nmodule load gcc/7.4.0\nmodule load R/4.0.3\n\nmkdir -p logs\n\n\n# Function to run snakemake\nrun_snakemake() {\n    local snake_file=$1\n    local config_file=$2\n\n    args='\n        -oo {log.out} \n        -eo {log.err} \n        -J {params.job_name}\n        -R \"rusage[mem={params.memory}] span[hosts=1]\"\n        -n {threads} '\n\n    snakemake -n \\\n        --snakefile $snake_file \\\n        --drmaa \"$args\" \\\n        --jobs 100 \\\n        --configfiles $config_file\n}\n\n\n# Run pipeline to process mNET-seq reads\npipe_dir=src/pipelines\nsamples=SAMPLES.yaml\n\nsnake=$pipe_dir/NETseq.snake\nconfig=NETseq.yaml\n\nrun_snakemake $snake \"$samples $config\"\n\n# Run pipeline to identify pause sites\nsnake=$pipe_dir/pauses.snake\nconfig=pauses.yaml\n\nrun_snakemake $snake \"$samples $config\"\n\n\n",
      "flux": "#!/usr/bin/env bash\n\n# Flux batch script\n#\n# NOTE: This script uses Snakemake's DRMAA integration with LSF-style arguments.\n# Flux does not provide a DRMAA interface by default, so this functionality cannot be translated directly.\n#\n# Performance implication of omission: without a Flux-targeting executor, Snakemake will not be able to\n# submit rules as separate scheduled jobs (reduced parallelism/throughput), unless you adapt it to a Flux\n# executor/plugin supported at your site.\n\n# This is a self-submitting Flux script: run it directly (e.g., `./netseq.flux.sh`).\n# It will submit itself to Flux with default resources (no explicit LSF CPU/mem/time were specified).\n\nJOBID=$(flux batch -N 1 -n 1 --wrap \"bash $0 __flux_inner\")\n\necho \"Submitted Flux job: $JOBID\"\n\nif [ \"${1:-}\" = \"__flux_inner\" ]; then\n  set -o nounset -o pipefail -o errexit -x\n\n  module load fastqc\n  module load bowtie2\n  module load samtools\n  module load subread\n  module load gcc/7.4.0\n  module load R/4.0.3\n\n  mkdir -p logs\n\n  run_snakemake() {\n      local snake_file=$1\n      local config_file=$2\n\n      args='\\\n          -oo {log.out} \\\n          -eo {log.err} \\\n          -J {params.job_name}\\\n          -R \"rusage[mem={params.memory}] span[hosts=1]\"\\\n          -n {threads} '\n\n      snakemake -n \\\n          --snakefile \"$snake_file\" \\\n          --drmaa \"$args\" \\\n          --jobs 100 \\\n          --configfiles $config_file\n  }\n\n  pipe_dir=src/pipelines\n  samples=SAMPLES.yaml\n\n  snake=$pipe_dir/NETseq.snake\n  config=NETseq.yaml\n  flux run -n 1 bash -lc \"run_snakemake '$snake' '$samples $config'\"\n\n  snake=$pipe_dir/pauses.snake\n  config=pauses.yaml\n  flux run -n 1 bash -lc \"run_snakemake '$snake' '$samples $config'\"\nfi\n",
